@'
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const {execFileSync} = require('node:child_process');
const yaml = require('yaml');
const name = 'gof-decorator';
const root = 'skills/'+name;
const baseline = JSON.parse(fs.readFileSync('docs/skill-validation/wave4-2026-10-16/baseline.json','utf8'));
const initial = baseline.packages.find(x=>x.name===name);
const files = [];
function walk(dir) { for (const e of fs.readdirSync(dir,{withFileTypes:true})) { const p=dir+'/'+e.name; if(e.isDirectory()) walk(p); else files.push(p); } }
walk(root); files.sort();
const manifest = yaml.parse(fs.readFileSync(root+'/skill.yaml','utf8'));
const entry = fs.readFileSync(root+'/SKILL.md','utf8');
const front = yaml.parse(entry.match(/^---\r?\n([\s\S]*?)\r?\n---/)[1]);
const localLinks=[];
for(const p of files.filter(x=>x.endsWith('.md'))) for(const m of fs.readFileSync(p,'utf8').matchAll(/\[[^\]]*\]\((?:<([^>]+)>|([^\s)]+))\)/g)) { const t=m[1]||m[2]; if(/^(?:https?:|mailto:|#)/.test(t)) continue; const resolved=path.resolve(path.dirname(p),decodeURIComponent(t.split('#')[0])); localLinks.push({file:p,target:t,exists:fs.existsSync(resolved)}); }
const referrals=[...(manifest.dependencies||[]),...(manifest.suggests||[])].map(v=>typeof v==='string'?v:v.name).map(n=>({name:n,exists:fs.existsSync('skills/'+n+'/SKILL.md')}));
const hashes=files.map(p=>({path:p,bytes:fs.statSync(p).size,sha256:crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex')}));
const same=JSON.stringify(hashes)===JSON.stringify(initial.files.map(({path,bytes,sha256})=>({path,bytes,sha256})).sort((a,b)=>a.path.localeCompare(b.path)));
const mismatches=hashes.filter(f=>{const b=initial.files.find(x=>x.path===f.path);return !b||b.sha256!==f.sha256||b.bytes!==f.bytes;});
const status=execFileSync('git',['status','--short','--untracked-files=all','--',root],{encoding:'utf8'}).trim();
const committed=yaml.parse(execFileSync('git',['show','HEAD:'+root+'/skill.yaml'],{encoding:'utf8'})).version;
const result={node:process.version,skill:name,versions:{committed,assignment:initial.initialVersion,final:manifest.version},initialStatus:initial.status,finalStatus:status,nameConsistent:front.name===manifest.name&&manifest.name===name,descriptionConsistent:front.description.trim()===manifest.description.trim(),fileCount:files.length,localLinks,referrals,allHashesEqualAssignment:files.length===initial.files.length&&mismatches.length===0,hashes};
console.log(JSON.stringify(result,null,2));
if(!result.nameConsistent||!result.descriptionConsistent||!result.allHashesEqualAssignment||status||localLinks.some(x=>!x.exists)||referrals.some(x=>!x.exists)||manifest.version!==initial.initialVersion||committed!==initial.committedVersion) process.exitCode=1;
'@ | node

