import java.util.List;

public interface ExportSession extends AutoCloseable {
    ExportSession label(String value);
    void append(String row);
    default void appendAll(List<String> rows) {
        for (String row : rows) append(row);
    }
    void flush();
    @Override void close();
}

import java.util.Objects;

public final class CountingSession implements ExportSession {
    private final ExportSession delegate;
    private long appended;
    public CountingSession(ExportSession delegate) {
        this.delegate = Objects.requireNonNull(delegate);
    }
    @Override public ExportSession label(String value) {
        delegate.label(value);
        return this;
    }
    @Override public void append(String row) {
        delegate.append(row);
        appended++;
    }
    public long appended() { return appended; }
    @Override public void flush() { delegate.flush(); }
    @Override public void close() { delegate.close(); }
}

import java.util.List;

public final class ExportService {
    private final SessionProvider provider;
    public ExportService(SessionProvider provider) { this.provider = provider; }
    public long export(List<String> rows) {
        try (var session = new CountingSession(provider.acquire())) {
            session.label("daily-export").appendAll(rows);
            session.flush();
            return session.appended();
        }
    }
}

